// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address alice, address bob) public {
        vm.assume(alice != address(0) && alice != address(c) && alice != bob);
        vm.assume(bob != address(0) && bob != address(c));
        depositAmount = bound(depositAmount, 1, 1000 ether);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        vm.deal(alice, depositAmount);
        vm.prank(alice);
        (bool s1,) = address(c).call{value: depositAmount}("");
        require(s1);

        vm.deal(bob, depositAmount);
        vm.prank(bob);
        (bool s2,) = address(c).call{value: depositAmount}("");
        require(s2);

        uint256 sumBefore = c.balances(alice) + c.balances(bob);
        uint256 contractEthBefore = address(c).balance;

        vm.prank(alice);
        try c.withdraw() {
        } catch { }

        uint256 sumAfter = c.balances(alice) + c.balances(bob);
        uint256 contractEthAfter = address(c).balance;

        assertTrue(sumAfter == contractEthAfter);
    }
}
